from fractions import Fraction
import itertools

target = Fraction(7, 330)
solutions = []

# Search space for a1, a2, a3. We know a_i must be smaller than 67.
# We start with a moderate upper bound for the initial systematic search.
MAX_A = 30 

print(f"Searching for distinct integers a1, a2, a3 < {MAX_A} such that Product((a_i-1)/a_i) = {target}")

# Iterate over distinct integers a1 < a2 < a3
for a1 in range(2, MAX_A + 1):
    for a2 in range(a1 + 1, MAX_A + 1):
        for a3 in range(a2 + 1, MAX_A + 1):
            # Check if any a_i is 67 (which is outside this loop but good practice)
            if a1 == 67 or a2 == 67 or a3 == 67:
                continue

            # Calculate the product P = (a1-1)/a1 * (a2-1)/a2 * (a3-1)/a3
            numerator = (a1 - 1) * (a2 - 1) * (a3 - 1)
            denominator = a1 * a2 * a3

            P = Fraction(numerator, denominator)

            if P == target:
                solutions.append((a1, a2, a3))

if solutions:
    print("Found solutions for (a1, a2, a3):")
    for sol in solutions:
        print(sol)
else:
    print("No solutions found for a1, a2, a3 <= 30.")

# Test a slightly larger range for a3, focusing on cases where a1 or a2 are very small
# Since 330 is relatively small, solutions should be found if they exist for small a_i.
# Let's extend the loop to see if a solution is missed just because the initial search limit was too low.

MAX_A_EXTENDED = 60 # We shouldn't need to go much past 60 if 67 is the other factor

solutions_extended = []
print("\nExtending search up to MAX_A = 60...")

for a1 in range(2, MAX_A_EXTENDED + 1):
    for a2 in range(a1 + 1, MAX_A_EXTENDED + 1):
        for a3 in range(a2 + 1, MAX_A_EXTENDED + 1):
            if a1 == 67 or a2 == 67 or a3 == 67:
                continue

            numerator = (a1 - 1) * (a2 - 1) * (a3 - 1)
            denominator = a1 * a2 * a3

            P = Fraction(numerator, denominator)

            if P == target:
                solutions_extended.append((a1, a2, a3))

if solutions_extended:
    print("Found extended solutions for (a1, a2, a3):")
    for sol in solutions_extended:
        print(sol)
else:
    print("No solutions found for a1, a2, a3 <= 60.")
